387  BOXA *
   388  pixLocateBarcodes(PIX     *pixs,
   389                    l_int32  thresh,
   390                    PIX    **ppixb,
   391                    PIX    **ppixm)
   392  {
   393  BOXA  *boxa;
   394  PIX   *pix8, *pixe, *pixb, *pixm;
   395
   396      PROCNAME("pixLocateBarcodes");
   397
   398      if (!pixs)
   399          return (BOXA *)ERROR_PTR("pixs not defined", procName, NULL);
   400
   401          /* Get an 8 bpp image, no cmap */
   402      if (pixGetDepth(pixs) == 8 && !pixGetColormap(pixs))
   403          pix8 = pixClone(pixs);
   404      else
   405          pix8 = pixConvertTo8(pixs, 0);
   406
   407          /* Get a 1 bpp image of the edges */
   408      pixe = pixSobelEdgeFilter(pix8, L_ALL_EDGES);
   409      pixb = pixThresholdToBinary(pixe, thresh);
   410      pixInvert(pixb, pixb);
   411      pixDestroy(&pix8);
   412      pixDestroy(&pixe);
   413
   414      pixm = pixGenerateBarcodeMask(pixb, MAX_SPACE_WIDTH, MAX_NOISE_WIDTH,
   415                                    MAX_NOISE_HEIGHT);
   416      boxa = pixConnComp(pixm, NULL, 8);
   417
   418      if (ppixb)
   419          *ppixb = pixb;
   420      else
   421          pixDestroy(&pixb);
   422      if (ppixm)
   423          *ppixm = pixm;
   424      else
   425          pixDestroy(&pixm);
   426
   427      return boxa;
   428  }
