   431  /*!
   432   * \brief   pixGenerateBarcodeMask()
   433   *
   434   * \param[in]    pixs       1 bpp
   435   * \param[in]    maxspace   largest space in the barcode, in pixels
   436   * \param[in]    nwidth     opening 'width' to remove noise
   437   * \param[in]    nheight    opening 'height' to remove noise
   438   * \return  pixm   mask over barcodes, or NULL if none found or on error
   439   *
   440   * <pre>
   441   * Notes:
   442   *      (1) For noise removal, 'width' and 'height' are referred to the
   443   *          barcode orientation.
   444   *      (2) If there is skew, the mask will not cover the barcode corners.
   445   * </pre>
   446   */
   447  static PIX *
   448  pixGenerateBarcodeMask(PIX     *pixs,
   449                         l_int32  maxspace,
   450                         l_int32  nwidth,
   451                         l_int32  nheight)
   452  {
   453  PIX  *pixt1, *pixt2, *pixd;
   454
   455      PROCNAME("pixGenerateBarcodeMask");
   456
   457      if (!pixs || pixGetDepth(pixs) != 1)
   458          return (PIX *)ERROR_PTR("pixs not defined", procName, NULL);
   459
   460          /* Identify horizontal barcodes */
   461      pixt1 = pixCloseBrick(NULL, pixs, maxspace + 1, 1);
   462      pixt2 = pixOpenBrick(NULL, pixs, maxspace + 1, 1);
   463      pixXor(pixt2, pixt2, pixt1);
   464      pixOpenBrick(pixt2, pixt2, nwidth, nheight);
   465      pixDestroy(&pixt1);
   466
   467          /* Identify vertical barcodes */
   468      pixt1 = pixCloseBrick(NULL, pixs, 1, maxspace + 1);
   469      pixd = pixOpenBrick(NULL, pixs, 1, maxspace + 1);
   470      pixXor(pixd, pixd, pixt1);
   471      pixOpenBrick(pixd, pixd, nheight, nwidth);
   472      pixDestroy(&pixt1);
   473
   474          /* Combine to get all barcodes */
   475      pixOr(pixd, pixd, pixt2);
   476      pixDestroy(&pixt2);
   477
   478      return pixd;
   479  }
