   482  /*------------------------------------------------------------------------*
   483   *                        Extract and deskew barcode                      *
   484   *------------------------------------------------------------------------*/
   485  /*!
   486   * \brief   pixDeskewBarcode()
   487   *
   488   * \param[in]    pixs        input image; 8 bpp
   489   * \param[in]    pixb        binarized edge-filtered input image
   490   * \param[in]    box         identified region containing barcode
   491   * \param[in]    margin      of extra pixels around box to extract
   492   * \param[in]    threshold   for binarization; ~20
   493   * \param[out]   pangle      [optional] in degrees, clockwise is positive
   494   * \param[out]   pconf       [optional] confidence
   495   * \return  pixd   deskewed barcode, or NULL on error
   496   *
   497   * <pre>
   498   * Notes:
   499   *     (1) The (optional) angle returned is the angle in degrees (cw positive)
   500   *         necessary to rotate the image so that it is deskewed.
   501   * </pre>
   502   */
   503  PIX *
   504  pixDeskewBarcode(PIX        *pixs,
   505                   PIX        *pixb,
   506                   BOX        *box,
   507                   l_int32     margin,
   508                   l_int32     threshold,
   509                   l_float32  *pangle,
   510                   l_float32  *pconf)
   511  {
   512  l_int32    x, y, w, h, n;
   513  l_float32  angle, angle1, angle2, conf, conf1, conf2, score1, score2, deg2rad;
   514  BOX       *boxe, *boxt;
   515  BOXA      *boxa, *boxat;
   516  PIX       *pixt1, *pixt2, *pixt3, *pixt4, *pixt5, *pixt6, *pixd;
   517
   518      PROCNAME("pixDeskewBarcode");
   519
   520      if (!pixs || pixGetDepth(pixs) != 8)
   521          return (PIX *)ERROR_PTR("pixs undefined or not 8 bpp", procName, NULL);
   522      if (!pixb || pixGetDepth(pixb) != 1)
   523          return (PIX *)ERROR_PTR("pixb undefined or not 1 bpp", procName, NULL);
   524      if (!box)
   525          return (PIX *)ERROR_PTR("box not defined or 1 bpp", procName, NULL);
   526
   527          /* Clip out */
   528      deg2rad = 3.1415926535 / 180.;
   529      boxGetGeometry(box, &x, &y, &w, &h);
   530      boxe = boxCreate(x - 25, y - 25, w + 51, h + 51);
   531      pixt1 = pixClipRectangle(pixb, boxe, NULL);
   532      pixt2 = pixClipRectangle(pixs, boxe, NULL);
   533      boxDestroy(&boxe);
   534
   535          /* Deskew, looking at all possible orientations over 180 degrees */
   536      pixt3 = pixRotateOrth(pixt1, 1);  /* look for vertical bar lines */
   537      pixt4 = pixClone(pixt1);   /* look for horizontal bar lines */
   538      pixFindSkewSweepAndSearchScore(pixt3, &angle1, &conf1, &score1,
   539                                     1, 1, 0.0, 45.0, 2.5, 0.01);
   540      pixFindSkewSweepAndSearchScore(pixt4, &angle2, &conf2, &score2,
   541                                     1, 1, 0.0, 45.0, 2.5, 0.01);
   542
   543          /* Because we're using the boundary pixels of the barcodes,
   544           * the peak can be sharper (and the confidence ratio higher)
   545           * from the signal across the top and bottom of the barcode.
   546           * However, the max score, which is the magnitude of the signal
   547           * at the optimum skew angle, will be smaller, so we use the
   548           * max score as the primary indicator of orientation. */
   549      if (score1 >= score2) {
   550          conf = conf1;
   551          if (conf1 > 6.0 && L_ABS(angle1) > 0.1) {
   552              angle = angle1;
   553              pixt5 = pixRotate(pixt2, deg2rad * angle1, L_ROTATE_AREA_MAP,
   554                                L_BRING_IN_WHITE, 0, 0);
   555          } else {
   556              angle = 0.0;
   557              pixt5 = pixClone(pixt2);
   558          }
   559      } else {  /* score2 > score1 */
   560          conf = conf2;
   561          pixt6 = pixRotateOrth(pixt2, 1);
   562          if (conf2 > 6.0 && L_ABS(angle2) > 0.1) {
   563              angle = 90.0 + angle2;
   564              pixt5 = pixRotate(pixt6, deg2rad * angle2, L_ROTATE_AREA_MAP,
   565                                L_BRING_IN_WHITE, 0, 0);
   566          } else {
   567              angle = 90.0;
   568              pixt5 = pixClone(pixt6);
   569          }
   570          pixDestroy(&pixt6);
   571      }
   572      pixDestroy(&pixt3);
   573      pixDestroy(&pixt4);
   574
   575          /* Extract barcode plus a margin around it */
   576      boxa = pixLocateBarcodes(pixt5, threshold, 0, 0);
   577      if ((n = boxaGetCount(boxa)) != 1) {
   578          L_WARNING("barcode mask in %d components\n", procName, n);
   579          boxat = boxaSort(boxa, L_SORT_BY_AREA, L_SORT_DECREASING, NULL);
   580      } else {
   581          boxat = boxaCopy(boxa, L_CLONE);
   582      }
   583      boxt = boxaGetBox(boxat, 0, L_CLONE);
   584      boxGetGeometry(boxt, &x, &y, &w, &h);
   585      boxe = boxCreate(x - margin, y - margin, w + 2 * margin,
   586                       h + 2 * margin);
   587      pixd = pixClipRectangle(pixt5, boxe, NULL);
   588      boxDestroy(&boxt);
   589      boxDestroy(&boxe);
   590      boxaDestroy(&boxa);
   591      boxaDestroy(&boxat);
   592
   593      if (pangle) *pangle = angle;
   594      if (pconf) *pconf = conf;
   595
   596      pixDestroy(&pixt1);
   597      pixDestroy(&pixt2);
   598      pixDestroy(&pixt5);
   599      return pixd;
   600  }
